WITH base_orders AS MATERIALIZED (SELECT o.id,o.customer_id,o.created_at FROM orders o WHERE lower(o.status)='completed' AND o.created_at::date>=DATE '2024-01-01'), eligible AS MATERIALIZED (SELECT c.id,c.region,c.segment FROM customers c WHERE c.active AND EXISTS (SELECT 1 FROM base_orders o JOIN order_items oi ON oi.order_id=o.id JOIN products p ON p.id=oi.product_id JOIN product_suppliers ps ON ps.product_id=p.id JOIN suppliers s ON s.id=ps.supplier_id JOIN shipments sh ON sh.order_id=o.id WHERE o.customer_id=c.id AND p.active AND s.risk_tier>=4 AND (sh.delivered_at IS NULL OR sh.delivered_at>sh.shipped_at+INTERVAL '10 days'))), captured AS (SELECT o.id,o.customer_id,o.created_at FROM base_orders o JOIN eligible e ON e.id=o.customer_id WHERE EXISTS (SELECT 1 FROM payments pay WHERE pay.order_id=o.id AND pay.status='captured')), captured_counts AS (SELECT customer_id,count(*) n FROM captured GROUP BY customer_id), item_totals AS (SELECT o.customer_id,sum((oi.quantity-COALESCE(r.quantity,0))*oi.unit_price) n FROM captured o JOIN order_items oi ON oi.order_id=o.id LEFT JOIN returns r ON r.order_id=oi.order_id AND r.line_no=oi.line_no GROUP BY o.customer_id), promo_totals AS (SELECT o.customer_id,sum(op.discount_amount) n FROM base_orders o JOIN eligible e ON e.id=o.customer_id JOIN order_promotions op ON op.order_id=o.id JOIN promotions pr ON pr.id=op.promotion_id WHERE pr.active GROUP BY o.customer_id), late_counts AS (SELECT o.customer_id,count(*) n FROM base_orders o JOIN eligible e ON e.id=o.customer_id JOIN shipments sh ON sh.order_id=o.id WHERE sh.delivered_at IS NULL OR sh.delivered_at>sh.shipped_at+INTERVAL '10 days' GROUP BY o.customer_id), risky_counts AS (SELECT o.customer_id,count(DISTINCT ps.supplier_id) n FROM base_orders o JOIN eligible e ON e.id=o.customer_id JOIN order_items oi ON oi.order_id=o.id JOIN product_suppliers ps ON ps.product_id=oi.product_id JOIN suppliers s ON s.id=ps.supplier_id WHERE s.risk_tier>=4 GROUP BY o.customer_id), last_orders AS (SELECT o.customer_id,max(o.created_at) n FROM base_orders o JOIN eligible e ON e.id=o.customer_id GROUP BY o.customer_id) SELECT e.id customer_id,e.region,e.segment,COALESCE(cc.n,0) captured_order_count,COALESCE(it.n,0)::numeric(20,2) net_item_revenue,COALESCE(pt.n,0)::numeric(18,2) active_promotion_discount,COALESCE(lc.n,0) late_shipment_count,COALESCE(rc.n,0) risky_supplier_count,lo.n last_completed_at FROM eligible e LEFT JOIN captured_counts cc ON cc.customer_id=e.id LEFT JOIN item_totals it ON it.customer_id=e.id LEFT JOIN promo_totals pt ON pt.customer_id=e.id LEFT JOIN late_counts lc ON lc.customer_id=e.id LEFT JOIN risky_counts rc ON rc.customer_id=e.id LEFT JOIN last_orders lo ON lo.customer_id=e.id;